import "array"
import "regexp"
import "strings"

// Same helper as the traffic dashboards: the CIDR box becomes an anchored
// prefix regex, the only form InfluxDB pushes down to storage. Prefix lengths
// other than /8, /16, /24 and /32 round DOWN to the enclosing octet boundary,
// so the range can be wider than typed -- never narrower.
cidrPrefix = (cidr) => {
    p = strings.split(v: cidr, t: "/")
    bits = if length(arr: p) > 1 then int(v: p[1]) else 32
    o = strings.split(v: p[0], t: ".")

    return
        if bits <= 8 then "^" + o[0] + "\\."
        else if bits <= 16 then "^" + o[0] + "\\." + o[1] + "\\."
        else if bits <= 24 then "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\."
        else "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\." + o[3] + "$"
}

cidrRe = if "${cidr}" == "" then /.*/ else regexp.compile(v: cidrPrefix(cidr: "${cidr}"))

base = from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "dns_query" and r._field == "count")
  |> filter(fn: (r) => r.src_ip =~ cidrRe)

// Two sum()s rather than one reduce() over the raw points: sum pushes down
// into InfluxDB and reduce does not, so the only rows reduce ever sees are
// the two below. The seed row is what keeps the table non-empty on a network
// with no DNS at all -- reduce over nothing yields nothing, and a blank tile
// and a working one look identical.
total = base |> group() |> sum()
  |> map(fn: (r) => ({k: "total", _value: float(v: r._value)}))
blocked = base
  |> filter(fn: (r) => r.result == "blocked")
  |> group() |> sum()
  |> map(fn: (r) => ({k: "blocked", _value: float(v: r._value)}))
seed = array.from(rows: [{k: "seed", _value: 0.0}])

union(tables: [total, blocked, seed])
  |> group()
  |> reduce(identity: {total: 0.0, blocked: 0.0}, fn: (r, accumulator) => ({
      total: accumulator.total + (if r.k == "total" then r._value else 0.0),
      blocked: accumulator.blocked + (if r.k == "blocked" then r._value else 0.0)}))
  |> map(fn: (r) => ({r with _value: if r.total > 0.0
                                     then r.blocked / r.total * 100.0
                                     else -1.0}))
  |> keep(columns: ["_value"])

import "regexp"
import "strings"

// Same helper as the traffic dashboards: the CIDR box becomes an anchored
// prefix regex, the only form InfluxDB pushes down to storage. Prefix lengths
// other than /8, /16, /24 and /32 round DOWN to the enclosing octet boundary,
// so the range can be wider than typed -- never narrower.
cidrPrefix = (cidr) => {
    p = strings.split(v: cidr, t: "/")
    bits = if length(arr: p) > 1 then int(v: p[1]) else 32
    o = strings.split(v: p[0], t: ".")

    return
        if bits <= 8 then "^" + o[0] + "\\."
        else if bits <= 16 then "^" + o[0] + "\\." + o[1] + "\\."
        else if bits <= 24 then "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\."
        else "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\." + o[3] + "$"
}

cidrRe = if "${cidr}" == "" then /.*/ else regexp.compile(v: cidrPrefix(cidr: "${cidr}"))

// Derived from the time range rather than from v.windowPeriod (which follows
// the panel's pixel width) and rather than pinned (which makes zooming inert):
// ~96 buckets however far you zoom, floored at the service's own flush
// interval, below which there is nothing finer to show.
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 30000000000 then 30000000000 else spanNs / 96
every = duration(v: everyNs)

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "dns_query" and r._field == "count")
  |> filter(fn: (r) => r.src_ip =~ cidrRe)
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> group(columns: ["result"])
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> keep(columns: ["_time", "_value", "result"])
